import os
import torch


class Config:
    """
    Configuration class for the Sentiment Extraction task.
    Centralizes hyperparameters, paths, and model settings.
    """

    # --- General Configuration ---
    seed = 42
    num_workers = 4
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    # --- Paths ---
    # Metadata paths (generated by the provided script)
    train_metadata_path = "./metadata/train.csv"
    val_metadata_path = "./metadata/val.csv"
    test_metadata_path = "./metadata/test.csv"

    # Original input path (useful if concatenating train+val for full CV)
    original_train_path = "./input/train.csv"

    # Output paths
    working_dir = "./working/idea_7/"
    submission_dir = "./submission"
    submission_path = os.path.join(submission_dir, "submission.csv")

    # Ensure working directories exist
    os.makedirs(working_dir, exist_ok=True)
    os.makedirs(submission_dir, exist_ok=True)

    # --- Model Configuration ---
    model_name = "microsoft/deberta-v3-large"
    # Dropout settings for the backbone
    hidden_dropout_prob = 0.1
    attention_probs_dropout_prob = 0.1

    # --- Tokenizer / Input ---
    # Max length based on analysis (tweets are short)
    max_len = 96

    # --- Training Hyperparameters ---
    epochs = 3

    # Batch Size Strategy:
    # A100 40GB can handle batch_size=8 for DeBERTa-Large with max_len=96.
    # We use gradient accumulation to achieve an effective batch size of 32.
    train_batch_size = 8
    gradient_accumulation_steps = 4
    valid_batch_size = 16

    # Optimizer
    learning_rate = 2e-5
    min_lr = 1e-6
    weight_decay = 0.01
    max_grad_norm = 1.0

    # Loss Function
    label_smoothing = 0.1

    # Scheduler
    scheduler_type = "cosine"
    warmup_ratio = 0.1

    # --- Adversarial Weight Perturbation (AWP) ---
    use_awp = True
    awp_lr = 1e-4
    awp_eps = 1e-4
    # Enable AWP after the first epoch to ensure stable initialization.
    # Epochs are 0-indexed, so 1 means starting at the second epoch.
    awp_start_epoch = 1

    # --- Cross Validation ---
    n_folds = 5

    # --- Debugging ---
    # If True, runs on a small subset of data for rapid testing
    debug = False
